(() => {
  'use strict';

  const STORAGE_KEY = 'gunr-contract-generator-v1';
  const CURRENT_KEY = 'gunr-contract-generator-current-v1';
  const LIBRARY = window.RTBO_CONTRACT_LIBRARY && Array.isArray(window.RTBO_CONTRACT_LIBRARY.items)
    ? window.RTBO_CONTRACT_LIBRARY
    : { name: 'RTBO Contract Library', version: '', date: '', archiveUrl: 'library/Contracts.zip', documentCount: 0, templateCount: 0, items: [] };
  const SPECIALTY_TEMPLATES = Array.isArray(window.RTBO_SPECIALTY_CONTRACTS) ? window.RTBO_SPECIALTY_CONTRACTS : [];
  const LIBRARY_ITEMS = [...LIBRARY.items, ...SPECIALTY_TEMPLATES];
  const LIBRARY_TEMPLATES = LIBRARY_ITEMS.filter((item) => !item.isGuide);
  const TEMPLATE_DEFINITIONS = [
    { key: '', label: 'Select agreement category', sections: [] },
    ...LIBRARY_TEMPLATES.map((item) => ({ key: item.key, label: `${item.code} — ${item.title}`, sections: item.clauses || [], libraryItem: item })),
    { key: 'custom', label: 'Custom Agreement', sections: [] }
  ];
  const GOT_U_NEX_REF_LOGO_DATA = 'data:image/png;base64,';
  const RTBO_LOGO_DATA = 'data:image/png;base64,';
  const CONTRACT_BRAND_PREVIEW = `<div class="contract-brand-header"><img src="assets/approved-got-u-nex-ref-logo.png" alt="Got U Nex Ref"><div class="contract-brand-header__center"><strong>RAISING THE BAR OFFICIATING INC.</strong><span>GOT U NEX REF CONTRACT SERVICES</span></div><img src="assets/approved-rtbo-logo.png" alt="Raising The Bar Officiating"></div>`;

  let context = { profile: {}, taxProfile: {}, schools: [], users: [], officials: [] };
  let contracts = loadContracts();
  let current = blankContract();
  let activeView = 'builder';
  let deleteId = '';
  let toastTimer;
  let previewedLibraryKey = '';
  let contractDocumentSyncStarted = false;

  const form = document.querySelector('[data-contract-form]');
  const clauseList = document.querySelector('[data-clause-list]');
  const preview = document.querySelector('[data-contract-preview]');
  const statusNode = document.querySelector('[data-preview-status]');
  const workspaceTitle = document.querySelector('[data-workspace-title]');
  const templateSelect = form.elements.templateKey;
  const toast = document.querySelector('[data-toast]');
  const confirmDialog = document.querySelector('[data-confirm-dialog]');
  const libraryDialog = document.querySelector('[data-library-dialog]');

  init();

  function init() {
    templateSelect.innerHTML = TEMPLATE_DEFINITIONS.map((template) => `<option value="${escapeHtml(template.key)}">${escapeHtml(template.label)}</option>`).join('');
    bindEvents();
    let savedId = '';
    try { savedId = localStorage.getItem(CURRENT_KEY) || ''; } catch {}
    if (savedId) {
      const saved = contracts.find((contract) => contract.id === savedId);
      if (saved) current = normalizeContract(saved);
    }
    populateForm(current);
    renderAll();
    if (window.parent !== window) window.parent.postMessage({ type: 'rtbo-contract-ready' }, '*');
  }

  function blankContract() {
    return {
      id: '', templateKey: '', sourceTemplateFile: '', title: '', status: 'Draft', contractNumber: '', effectiveDate: '', endDate: '', governingState: '', renewalTerms: '', preamble: '',
      partyOneSource: '', partyOneName: '', partyOneContact: '', partyOneEmail: '', partyOnePhone: '', partyOneAddress: '',
      partyTwoSource: '', partyTwoName: '', partyTwoContact: '', partyTwoEmail: '', partyTwoPhone: '', partyTwoAddress: '',
      scope: '', compensation: '', paymentSchedule: '', expenses: '', compliance: '', clauses: [],
      partyOneSigner: '', partyOneSignerTitle: '', partyOneSignedDate: '', partyOneSignature: '',
      partyTwoSigner: '', partyTwoSignerTitle: '', partyTwoSignedDate: '', partyTwoSignature: '', internalNotes: '',
      createdAt: '', updatedAt: ''
    };
  }

  function normalizeContract(contract) {
    return { ...blankContract(), ...(contract || {}), clauses: Array.isArray(contract?.clauses) ? contract.clauses.map((clause) => ({ id: clause.id || uid('section'), title: String(clause.title || ''), body: String(clause.body || '') })) : [] };
  }

  function loadContracts() {
    try {
      const value = JSON.parse(localStorage.getItem(STORAGE_KEY));
      return Array.isArray(value) ? value.map(normalizeContract) : [];
    } catch { return []; }
  }

  function persistContracts() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(contracts));
      if (current.id) localStorage.setItem(CURRENT_KEY, current.id);
      else localStorage.removeItem(CURRENT_KEY);
    } catch {}
  }

  function uid(prefix) {
    return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  function escapeHtml(value = '') {
    return String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
  }

  function safeText(value = '') {
    return escapeHtml(value).replace(/\n/g, '<br>');
  }

  function formatDate(value) {
    if (!value) return '';
    const date = new Date(`${value}T12:00:00`);
    return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).format(date);
  }

  function bindEvents() {
    window.addEventListener('message', (event) => {
      if (event.data?.type === 'gunr-dashboard-context') applyDashboardContext(event.data.payload || {});
    });

    document.addEventListener('click', (event) => {
      const viewButton = event.target.closest('[data-view]');
      if (viewButton) { setView(viewButton.dataset.view); return; }
      const control = event.target.closest('[data-action]');
      if (!control) return;
      const action = control.dataset.action;
      if (action === 'new-contract') { newContract(); return; }
      if (action === 'save-contract') { saveCurrent(); return; }
      if (action === 'add-clause') { addClause(); return; }
      if (action === 'remove-clause') { removeClause(control.dataset.id); return; }
      if (action === 'print-contract') { syncFromForm(); window.print(); return; }
      if (action === 'download-html') { syncFromForm(); downloadHtml(current); return; }
      if (action === 'download-json') { syncFromForm(); downloadFile(contractFilename(current, 'json'), JSON.stringify(current, null, 2), 'application/json'); return; }
      if (action === 'edit-contract') { openContract(control.dataset.id); return; }
      if (action === 'duplicate-contract') { duplicateContract(control.dataset.id); return; }
      if (action === 'download-saved-contract') { const saved = contracts.find((contract) => contract.id === control.dataset.id); if (saved) downloadHtml(saved); return; }
      if (action === 'delete-contract') { deleteId = control.dataset.id || ''; confirmDialog.showModal(); return; }
      if (action === 'preview-library-document') { openLibraryPreview(control.dataset.key); return; }
      if (action === 'preview-current-template') { const item = libraryItemForContract(current); if (item) openLibraryPreview(item.key); return; }
      if (action === 'use-library-template') { useLibraryTemplate(control.dataset.key); return; }
      if (action === 'use-previewed-template') { useLibraryTemplate(previewedLibraryKey); libraryDialog.close(); return; }
      if (action === 'close-library-preview') { libraryDialog.close(); return; }
    });

    form.addEventListener('submit', (event) => { event.preventDefault(); saveCurrent(); });
    form.addEventListener('input', () => { syncFromForm(); renderPreview(); });
    form.addEventListener('change', (event) => {
      if (event.target === templateSelect) applyTemplate(event.target.value);
      if (event.target.matches('[data-party-source]')) applyPartySource(event.target.dataset.partySource, event.target.value);
      syncFromForm(); renderPreview();
    });

    document.querySelector('[data-contract-search]').addEventListener('input', renderSavedContracts);
    document.querySelector('[data-contract-status]').addEventListener('change', renderSavedContracts);
    document.querySelector('[data-library-search]').addEventListener('input', renderContractLibrary);
    document.querySelector('[data-library-category]').addEventListener('change', renderContractLibrary);
    confirmDialog.addEventListener('close', () => {
      if (confirmDialog.returnValue === 'confirm' && deleteId) deleteContract(deleteId);
      deleteId = '';
    });
  }

  function dashboardParties() {
    const parties = [];
    const profile = context.profile || {};
    const tax = context.taxProfile || {};
    const profileName = [profile.firstName, profile.lastName].filter(Boolean).join(' ').trim();
    const businessName = String(tax.businessName || '').trim();
    const legalName = String(tax.legalName || '').trim();
    const profileAddress = [tax.mailingAddress, [tax.city || profile.city, tax.region || profile.region, tax.postalCode].filter(Boolean).join(', ')].filter(Boolean).join('\n');
    if (businessName || legalName || profileName) {
      parties.push({
        id: 'dashboard-profile', type: 'Dashboard Profile', name: businessName || legalName || profileName,
        contact: profileName, email: profile.email || '', phone: profile.phone || '', address: profileAddress
      });
    }
    (context.schools || []).forEach((school, index) => {
      if (!school?.name) return;
      parties.push({ id: `school-${school.id || index}`, type: school.type || 'School or Organization', name: school.name, contact: school.contactName || school.athleticDirector || school.headCoach || '', email: school.email || school.athleticDirectorEmail || school.headCoachEmail || '', phone: school.phone || school.athleticDirectorPhone || school.headCoachPhone || '', address: school.venueAddress || '' });
    });
    (context.users || []).forEach((user, index) => {
      const name = [user?.firstName, user?.lastName].filter(Boolean).join(' ').trim() || user?.displayName || user?.name || '';
      if (!name) return;
      parties.push({ id: `user-${user.id || index}`, type: user.role || 'Dashboard User', name, contact: name, email: user.email || '', phone: user.phone || user.mobilePhone || '', address: [user.address, [user.city, user.region || user.state, user.postalCode].filter(Boolean).join(', ')].filter(Boolean).join('\n') });
    });
    (context.officials || []).forEach((official, index) => {
      const name = [official?.firstName, official?.lastName].filter(Boolean).join(' ').trim() || official?.name || official?.fullName || '';
      if (!name) return;
      parties.push({ id: `official-${official.id || index}`, type: 'Official', name, contact: name, email: official.email || '', phone: official.phone || official.mobilePhone || '', address: [official.address, [official.city, official.region || official.state, official.postalCode].filter(Boolean).join(', ')].filter(Boolean).join('\n') });
    });
    const seen = new Set();
    return parties.filter((party) => {
      const key = [party.type, party.name, party.email].join('|').toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function applyDashboardContext(payload) {
    context = {
      profile: payload.profile && typeof payload.profile === 'object' ? payload.profile : {},
      taxProfile: payload.taxProfile && typeof payload.taxProfile === 'object' ? payload.taxProfile : {},
      schools: Array.isArray(payload.schools) ? payload.schools : [],
      users: Array.isArray(payload.users) ? payload.users : [],
      officials: Array.isArray(payload.officials) ? payload.officials : []
    };
    updateProfileChip();
    renderPartySources();
    renderPartyDirectory();
    if (!current.id && !current.partyOneName) {
      const preferred = dashboardParties()[0];
      if (preferred) {
        current.partyOneSource = preferred.id;
        setPartyFields('one', preferred);
        populateForm(current);
      }
    }
    renderPreview();
    if (!contractDocumentSyncStarted) {
      contractDocumentSyncStarted = true;
      syncAllContractsToDashboard();
    }
  }

  function updateProfileChip() {
    const profile = context.profile || {};
    const name = [profile.firstName, profile.lastName].filter(Boolean).join(' ').trim();
    const chip = document.querySelector('[data-profile-chip]');
    chip.hidden = !name;
    if (!name) return;
    document.querySelector('[data-profile-initials]').textContent = `${profile.firstName?.[0] || ''}${profile.lastName?.[0] || ''}`.toUpperCase();
    document.querySelector('[data-profile-name]').textContent = name;
    document.querySelector('[data-profile-role]').textContent = profile.role || '';
  }

  function renderPartySources() {
    const parties = dashboardParties();
    const options = `<option value="">Enter party manually</option>${parties.map((party) => `<option value="${escapeHtml(party.id)}">${escapeHtml(`${party.name} — ${party.type}`)}</option>`).join('')}`;
    form.querySelectorAll('[data-party-source]').forEach((select) => {
      const value = select.dataset.partySource === 'one' ? current.partyOneSource : current.partyTwoSource;
      select.innerHTML = options;
      select.value = parties.some((party) => party.id === value) ? value : '';
    });
    document.querySelector('[data-party-count]').textContent = String(parties.length);
  }

  function applyPartySource(side, id) {
    const party = dashboardParties().find((item) => item.id === id);
    if (!party) return;
    setPartyFields(side, party);
  }

  function setPartyFields(side, party) {
    const prefix = side === 'one' ? 'partyOne' : 'partyTwo';
    current[`${prefix}Source`] = party.id || '';
    current[`${prefix}Name`] = party.name || '';
    current[`${prefix}Contact`] = party.contact || '';
    current[`${prefix}Email`] = party.email || '';
    current[`${prefix}Phone`] = party.phone || '';
    current[`${prefix}Address`] = party.address || '';
    Object.entries({ [`${prefix}Source`]: current[`${prefix}Source`], [`${prefix}Name`]: current[`${prefix}Name`], [`${prefix}Contact`]: current[`${prefix}Contact`], [`${prefix}Email`]: current[`${prefix}Email`], [`${prefix}Phone`]: current[`${prefix}Phone`], [`${prefix}Address`]: current[`${prefix}Address`] }).forEach(([name, value]) => { if (form.elements[name]) form.elements[name].value = value; });
  }

  function applyTemplate(key) {
    current.templateKey = key;
    const template = TEMPLATE_DEFINITIONS.find((item) => item.key === key);
    if (!template) return;
    if (template.libraryItem) {
      const item = template.libraryItem;
      if (!form.elements.title.value.trim()) form.elements.title.value = item.title;
      if (!form.elements.preamble.value.trim() && item.preamble) form.elements.preamble.value = item.preamble;
      current.sourceTemplateFile = item.filename;
      form.elements.sourceTemplateFile.value = item.filename;
      if (!current.clauses.length && Array.isArray(item.clauses)) {
        current.clauses = item.clauses.map((clause) => ({ id: uid('section'), title: clause.title || '', body: clause.body || '' }));
        renderClauses();
      }
      renderTemplateSource();
      return;
    }
    if (!form.elements.title.value.trim() && key === 'custom') form.elements.title.value = '';
    if (key === 'custom') {
      current.sourceTemplateFile = '';
      form.elements.sourceTemplateFile.value = '';
      renderTemplateSource();
    }
  }

  function libraryItemForContract(contract) {
    if (!contract) return null;
    return LIBRARY_TEMPLATES.find((item) => item.key === contract.templateKey || item.filename === contract.sourceTemplateFile) || null;
  }

  function hasUnsavedDraftContent() {
    syncFromForm();
    return Boolean(current.title || current.partyTwoName || current.contractNumber || current.effectiveDate || current.scope || current.preamble || current.clauses.some((clause) => clause.title || clause.body));
  }

  function useLibraryTemplate(key) {
    const item = LIBRARY_TEMPLATES.find((entry) => entry.key === key);
    if (!item) return;
    if (hasUnsavedDraftContent() && !window.confirm('Replace the current unsaved builder content with this RTBO contract template?')) return;
    const partyOne = {
      source: current.partyOneSource || '', name: current.partyOneName || '', contact: current.partyOneContact || '',
      email: current.partyOneEmail || '', phone: current.partyOnePhone || '', address: current.partyOneAddress || ''
    };
    current = blankContract();
    current.templateKey = item.key;
    current.sourceTemplateFile = item.filename;
    current.title = item.title;
    current.preamble = item.preamble || '';
    current.clauses = (item.clauses || []).map((clause) => ({ id: uid('section'), title: clause.title || '', body: clause.body || '' }));
    if (partyOne.name) {
      current.partyOneSource = partyOne.source;
      current.partyOneName = partyOne.name;
      current.partyOneContact = partyOne.contact;
      current.partyOneEmail = partyOne.email;
      current.partyOnePhone = partyOne.phone;
      current.partyOneAddress = partyOne.address;
    }
    populateForm(current);
    try { localStorage.removeItem(CURRENT_KEY); } catch {}
    setView('builder');
    showToast(`${item.title} is open as a new unsaved contract.`);
  }

  function renderTemplateSource() {
    const item = libraryItemForContract(current);
    const source = document.querySelector('[data-template-source]');
    source.hidden = !item;
    if (!item) return;
    document.querySelector('[data-template-source-name]').textContent = item.filename;
    const link = document.querySelector('[data-template-source-download]');
    link.href = item.url;
    link.download = item.filename;
  }

  function addClause() {
    syncFromForm();
    current.clauses.push({ id: uid('section'), title: '', body: '' });
    renderClauses();
    renderPreview();
  }

  function removeClause(id) {
    syncFromForm();
    current.clauses = current.clauses.filter((clause) => clause.id !== id);
    renderClauses();
    renderPreview();
  }

  function renderClauses() {
    if (!current.clauses.length) {
      clauseList.innerHTML = '<div class="empty-clauses">No contract sections have been added.</div>';
      return;
    }
    clauseList.innerHTML = current.clauses.map((clause, index) => `<div class="clause-row" data-clause-id="${escapeHtml(clause.id)}"><label><span>Section ${index + 1} Title</span><input type="text" data-clause-title value="${escapeHtml(clause.title)}"></label><label><span>Section Language</span><textarea rows="5" data-clause-body>${escapeHtml(clause.body)}</textarea></label><button type="button" data-action="remove-clause" data-id="${escapeHtml(clause.id)}" aria-label="Remove section">×</button></div>`).join('');
    clauseList.querySelectorAll('input, textarea').forEach((control) => control.addEventListener('input', () => { syncFromForm(); renderPreview(); }));
  }

  function syncFromForm() {
    const data = Object.fromEntries(new FormData(form).entries());
    Object.keys(blankContract()).forEach((key) => {
      if (key === 'clauses' || key === 'createdAt' || key === 'updatedAt') return;
      if (Object.prototype.hasOwnProperty.call(data, key)) current[key] = String(data[key] || '').trim();
    });
    current.clauses = [...clauseList.querySelectorAll('[data-clause-id]')].map((row) => ({ id: row.dataset.clauseId || uid('section'), title: row.querySelector('[data-clause-title]').value.trim(), body: row.querySelector('[data-clause-body]').value.trim() }));
  }

  function populateForm(contract) {
    current = normalizeContract(contract);
    Object.entries(current).forEach(([key, value]) => {
      if (key === 'clauses' || !form.elements[key]) return;
      form.elements[key].value = value ?? '';
    });
    renderPartySources();
    renderClauses();
    renderPreview();
    renderTemplateSource();
    workspaceTitle.textContent = current.title || 'New Contract';
  }

  function saveCurrent() {
    syncFromForm();
    if (!form.reportValidity()) {
      form.querySelector(':invalid')?.focus();
      showToast('Complete the required contract fields.');
      return;
    }
    const now = new Date().toISOString();
    if (!current.id) current.id = uid('contract');
    if (!current.createdAt) current.createdAt = now;
    current.updatedAt = now;
    const index = contracts.findIndex((contract) => contract.id === current.id);
    if (index >= 0) contracts[index] = normalizeContract(current);
    else contracts.unshift(normalizeContract(current));
    persistContracts();
    workspaceTitle.textContent = current.title;
    renderSavedContracts();
    updateCounts();
    sendContractToDashboard(current);
    showToast('Contract saved in this browser.');
  }

  function newContract() {
    current = blankContract();
    populateForm(current);
    try { localStorage.removeItem(CURRENT_KEY); } catch {}
    setView('builder');
    form.elements.title.focus();
  }

  function openContract(id) {
    const contract = contracts.find((item) => item.id === id);
    if (!contract) return;
    populateForm(contract);
    try { localStorage.setItem(CURRENT_KEY, contract.id); } catch {}
    setView('builder');
  }

  function duplicateContract(id) {
    const source = contracts.find((item) => item.id === id);
    if (!source) return;
    const copy = normalizeContract(source);
    copy.id = '';
    copy.contractNumber = '';
    copy.status = 'Draft';
    copy.createdAt = '';
    copy.updatedAt = '';
    copy.title = copy.title ? `${copy.title} Copy` : '';
    copy.clauses = copy.clauses.map((clause) => ({ ...clause, id: uid('section') }));
    populateForm(copy);
    try { localStorage.removeItem(CURRENT_KEY); } catch {}
    setView('builder');
    showToast('A new unsaved copy is open.');
  }

  function deleteContract(id) {
    contracts = contracts.filter((contract) => contract.id !== id);
    if (current.id === id) newContract();
    persistContracts();
    renderSavedContracts();
    updateCounts();
    showToast('Contract deleted.');
  }

  function renderPreview() {
    statusNode.textContent = current.status || 'Draft';
    workspaceTitle.textContent = current.title || 'New Contract';
    const hasContent = current.title || current.partyOneName || current.partyTwoName || current.preamble || current.scope || current.clauses.some((clause) => clause.title || clause.body);
    if (!hasContent) {
      preview.innerHTML = '<div class="paper-empty"><div><strong>Contract preview</strong><p>Enter contract details to build the document.</p></div></div>';
      return;
    }
    const meta = [current.contractNumber ? `Contract ${current.contractNumber}` : '', current.effectiveDate ? `Effective ${formatDate(current.effectiveDate)}` : '', current.status || ''].filter(Boolean).join(' · ');
    const parties = current.partyOneName && current.partyTwoName ? `<p>This agreement is entered into by and between <strong>${safeText(current.partyOneName)}</strong> and <strong>${safeText(current.partyTwoName)}</strong>${current.effectiveDate ? `, effective ${safeText(formatDate(current.effectiveDate))}` : ''}.</p>` : '';
    const details = [
      current.scope ? ['Scope of Services', current.scope] : null,
      current.compensation || current.paymentSchedule ? ['Compensation and Payment', [current.compensation, current.paymentSchedule].filter(Boolean).join('\n')] : null,
      current.expenses ? ['Expenses', current.expenses] : null,
      current.compliance ? ['Insurance and Compliance', current.compliance] : null,
      ...current.clauses.filter((clause) => clause.title || clause.body).map((clause) => [clause.title || 'Contract Section', clause.body]),
      current.governingState ? ['Governing Law', current.governingState] : null,
      current.renewalTerms ? ['Renewal', current.renewalTerms] : null
    ].filter(Boolean);
    const signatures = current.partyOneSigner || current.partyTwoSigner || current.partyOneSignature || current.partyTwoSignature ? `<div class="signature-grid"><div class="signature-block"><div class="signature-text">${safeText(current.partyOneSignature)}</div><strong>${safeText(current.partyOneSigner || current.partyOneName)}</strong><br>${safeText(current.partyOneSignerTitle)}${current.partyOneSignedDate ? `<br>${safeText(formatDate(current.partyOneSignedDate))}` : ''}</div><div class="signature-block"><div class="signature-text">${safeText(current.partyTwoSignature)}</div><strong>${safeText(current.partyTwoSigner || current.partyTwoName)}</strong><br>${safeText(current.partyTwoSignerTitle)}${current.partyTwoSignedDate ? `<br>${safeText(formatDate(current.partyTwoSignedDate))}` : ''}</div></div>` : '';
    preview.innerHTML = `${CONTRACT_BRAND_PREVIEW}<h1>${safeText(current.title || 'Agreement')}</h1>${meta ? `<p class="contract-meta">${safeText(meta)}</p>` : ''}${current.preamble ? `<p class="contract-preamble">${safeText(current.preamble)}</p>` : ''}${parties}${details.map(([title, body], index) => `<section><h2>${index + 1}. ${safeText(title)}</h2>${body ? `<p>${safeText(body)}</p>` : ''}</section>`).join('')}${current.endDate ? `<p><strong>End date:</strong> ${safeText(formatDate(current.endDate))}</p>` : ''}${signatures}`;
  }

  function renderSavedContracts() {
    const list = document.querySelector('[data-contract-list]');
    const query = document.querySelector('[data-contract-search]').value.trim().toLowerCase();
    const status = document.querySelector('[data-contract-status]').value;
    const rows = contracts.filter((contract) => {
      if (status && contract.status !== status) return false;
      if (!query) return true;
      return [contract.title, contract.contractNumber, contract.partyOneName, contract.partyTwoName, contract.status].join(' ').toLowerCase().includes(query);
    }).sort((a, b) => String(b.updatedAt || b.createdAt || '').localeCompare(String(a.updatedAt || a.createdAt || '')));
    if (!rows.length) {
      list.innerHTML = '<div class="empty-state"><strong>No saved contracts</strong><p>Create and save a contract to add it to this list.</p></div>';
      return;
    }
    list.innerHTML = rows.map((contract) => `<article class="contract-row"><div><h3>${escapeHtml(contract.title)}</h3><p>${escapeHtml([contract.partyOneName, contract.partyTwoName].filter(Boolean).join(' ↔ '))}</p><small>${escapeHtml(contract.contractNumber || '')}</small></div><span class="status-badge">${escapeHtml(contract.status || 'Draft')}</span><div><small>Updated</small><p>${escapeHtml(contract.updatedAt ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(contract.updatedAt)) : '')}</p></div><div class="contract-row__actions"><button class="button button--quiet" type="button" data-action="edit-contract" data-id="${escapeHtml(contract.id)}">Open</button><button class="button button--quiet" type="button" data-action="duplicate-contract" data-id="${escapeHtml(contract.id)}">Duplicate</button><button class="button button--quiet" type="button" data-action="download-saved-contract" data-id="${escapeHtml(contract.id)}">Download</button><button class="button button--danger" type="button" data-action="delete-contract" data-id="${escapeHtml(contract.id)}">Delete</button></div></article>`).join('');
  }

  function renderPartyDirectory() {
    const directory = document.querySelector('[data-party-directory]');
    const parties = dashboardParties();
    if (!parties.length) {
      directory.innerHTML = '<div class="empty-state"><strong>No dashboard parties</strong><p>Add a profile, school, organization, official, or user record in the dashboard.</p></div>';
      return;
    }
    directory.innerHTML = `<div class="directory-grid">${parties.map((party) => `<article class="party-card"><p class="party-card__type">${escapeHtml(party.type)}</p><h3>${escapeHtml(party.name)}</h3>${party.contact ? `<p>${escapeHtml(party.contact)}</p>` : ''}${party.email ? `<small>${escapeHtml(party.email)}</small>` : ''}${party.phone ? `<small>${escapeHtml(party.phone)}</small>` : ''}${party.address ? `<small>${safeText(party.address)}</small>` : ''}</article>`).join('')}</div>`;
  }

  function formatBytes(bytes) {
    const value = Number(bytes) || 0;
    if (value < 1024) return `${value} B`;
    if (value < 1024 * 1024) return `${Math.round(value / 1024)} KB`;
    return `${(value / (1024 * 1024)).toFixed(1)} MB`;
  }

  function renderContractLibraryFilters() {
    const select = document.querySelector('[data-library-category]');
    const selected = select.value;
    const categories = [...new Set(LIBRARY_ITEMS.map((item) => item.category).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    select.innerHTML = `<option value="">All categories</option>${categories.map((category) => `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join('')}`;
    select.value = categories.includes(selected) ? selected : '';
  }

  function renderContractLibrary() {
    const list = document.querySelector('[data-library-list]');
    const query = document.querySelector('[data-library-search]').value.trim().toLowerCase();
    const category = document.querySelector('[data-library-category]').value;
    const rows = LIBRARY_ITEMS.filter((item) => {
      if (category && item.category !== category) return false;
      if (!query) return true;
      return [item.code, item.title, item.category, item.primaryUse, item.filename].join(' ').toLowerCase().includes(query);
    });
    if (!rows.length) {
      list.innerHTML = '<div class="empty-state"><strong>No matching RTBO documents</strong><p>Change the library search or category filter.</p></div>';
      return;
    }
    list.innerHTML = rows.map((item) => `<article class="library-card${item.isGuide ? ' library-card--guide' : ''}"><div class="library-card__code">${escapeHtml(item.code)}</div><div class="library-card__body"><p class="party-card__type">${escapeHtml(item.category)}</p><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.primaryUse || item.subtitle || '')}</p><div class="library-card__meta"><span>${escapeHtml(formatBytes(item.fileSize))}</span><span>${escapeHtml(String(item.clauses?.length || 0))} sections</span><span>Original DOCX</span></div></div><div class="library-card__actions"><button class="button button--quiet" type="button" data-action="preview-library-document" data-key="${escapeHtml(item.key)}">Preview</button>${item.isGuide ? '' : `<button class="button button--primary" type="button" data-action="use-library-template" data-key="${escapeHtml(item.key)}">Use in Builder</button>`}<a class="button button--quiet" href="${escapeHtml(item.url)}" download="${escapeHtml(item.filename)}">Download DOCX</a></div></article>`).join('');
  }

  function renderLibraryTable(rows) {
    if (!Array.isArray(rows) || !rows.length) return '';
    return `<div class="library-preview-table-wrap"><table><tbody>${rows.map((row, rowIndex) => `<tr>${row.map((cell) => rowIndex === 0 ? `<th>${safeText(cell)}</th>` : `<td>${safeText(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }

  function openLibraryPreview(key) {
    const item = LIBRARY_ITEMS.find((entry) => entry.key === key);
    if (!item) return;
    previewedLibraryKey = item.key;
    document.querySelector('[data-library-preview-code]').textContent = `${item.code} · ${item.category}`;
    document.querySelector('[data-library-preview-title]').textContent = item.title;
    const download = document.querySelector('[data-library-preview-download]');
    download.href = item.url;
    download.download = item.filename;
    const useButton = libraryDialog.querySelector('[data-action="use-previewed-template"]');
    useButton.hidden = Boolean(item.isGuide);
    const notice = item.useNotice ? `<aside class="library-use-notice"><strong>Important Use Notice</strong><p>${safeText(item.useNotice.replace(/^IMPORTANT USE NOTICE\.?\s*/i, ''))}</p></aside>` : '';
    const preamble = item.preamble ? `<section><h3>Document Introduction</h3><p>${safeText(item.preamble)}</p></section>` : '';
    const clauses = (item.clauses || []).map((clause, index) => `<section><h3>${index + 1}. ${safeText(clause.title)}</h3><p>${safeText(clause.body)}</p></section>`).join('');
    const tables = (item.tables || []).map((table, index) => `<section><h3>${item.isGuide ? 'Reference Table' : 'Schedule / Signature Table'} ${index + 1}</h3>${renderLibraryTable(table)}</section>`).join('');
    document.querySelector('[data-library-document-preview]').innerHTML = `<div class="library-document-brand"><img src="assets/approved-got-u-nex-ref-logo.png" alt="Got U Nex Ref"><strong>RAISING THE BAR OFFICIATING INC.</strong><img src="assets/approved-rtbo-logo.png" alt="Raising The Bar Officiating"></div>${notice}<div class="library-preview-meta"><span>${escapeHtml(item.filename)}</span><span>${escapeHtml(formatBytes(item.fileSize))}</span><span>Branded execution-ready DOCX included</span></div>${preamble}${clauses}${tables}`;
    libraryDialog.showModal();
  }

  function setView(view) {
    activeView = ['builder', 'library', 'saved', 'parties'].includes(view) ? view : 'builder';
    document.querySelectorAll('[data-view]').forEach((button) => button.classList.toggle('is-active', button.dataset.view === activeView));
    document.querySelectorAll('[data-view-panel]').forEach((panel) => panel.classList.toggle('is-active', panel.dataset.viewPanel === activeView));
    if (activeView === 'library') renderContractLibrary();
    if (activeView === 'saved') renderSavedContracts();
    if (activeView === 'parties') renderPartyDirectory();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function renderAll() {
    renderPartySources();
    renderClauses();
    renderPreview();
    renderTemplateSource();
    renderContractLibraryFilters();
    renderContractLibrary();
    renderSavedContracts();
    renderPartyDirectory();
    updateCounts();
  }

  function updateCounts() {
    document.querySelector('[data-saved-count]').textContent = String(contracts.length);
    document.querySelector('[data-party-count]').textContent = String(dashboardParties().length);
    document.querySelector('[data-library-count]').textContent = String(LIBRARY_TEMPLATES.length);
    document.querySelector('[data-library-template-count]').textContent = String(LIBRARY_TEMPLATES.length);
    document.querySelector('[data-library-category-count]').textContent = String(new Set(LIBRARY_TEMPLATES.map((item) => item.category)).size);
  }

  function showToast(message) {
    clearTimeout(toastTimer);
    toast.textContent = message;
    toast.hidden = false;
    toastTimer = setTimeout(() => { toast.hidden = true; }, 2800);
  }

  function contractFilename(contract, extension) {
    const base = String(contract.title || contract.contractNumber || 'contract').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'contract';
    return `${base}.${extension}`;
  }

  function documentHtml(contract) {
    const normalized = normalizeContract(contract);
    const meta = [normalized.contractNumber ? `Contract ${normalized.contractNumber}` : '', normalized.effectiveDate ? `Effective ${formatDate(normalized.effectiveDate)}` : '', normalized.status].filter(Boolean).join(' · ');
    const sections = [
      normalized.scope ? ['Scope of Services', normalized.scope] : null,
      normalized.compensation || normalized.paymentSchedule ? ['Compensation and Payment', [normalized.compensation, normalized.paymentSchedule].filter(Boolean).join('\n')] : null,
      normalized.expenses ? ['Expenses', normalized.expenses] : null,
      normalized.compliance ? ['Insurance and Compliance', normalized.compliance] : null,
      ...normalized.clauses.filter((clause) => clause.title || clause.body).map((clause) => [clause.title || 'Contract Section', clause.body]),
      normalized.governingState ? ['Governing Law', normalized.governingState] : null,
      normalized.renewalTerms ? ['Renewal', normalized.renewalTerms] : null
    ].filter(Boolean);
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(normalized.title || 'Contract')}</title><style>body{max-width:8.5in;margin:0 auto;padding:.65in;font-family:Georgia,serif;color:#111;line-height:1.55}.brand{display:grid;grid-template-columns:85px 1fr 85px;align-items:center;gap:14px;padding-bottom:12px;margin-bottom:22px;border-bottom:2px solid #bd4e14}.brand img{width:78px;height:78px;object-fit:contain}.brand img:last-child{justify-self:end}.brand div{text-align:center;font:700 12px Arial,sans-serif;letter-spacing:.08em}.brand div span{display:block;margin-top:4px;font-size:16px;color:#666}h1{text-align:center;text-transform:uppercase;font-size:22px}h2{margin-top:24px;font-size:16px;text-transform:uppercase}.meta{text-align:center;color:#555;font:12px Arial,sans-serif}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:55px}.signature{border-top:1px solid #333;padding-top:8px}.signature em{display:block;min-height:35px;font:22px cursive}@media print{body{padding:.45in}}</style></head><body><div class="brand"><img src="${GOT_U_NEX_REF_LOGO_DATA}" alt="Got U Nex Ref"><div>RAISING THE BAR OFFICIATING INC.<span>GOT U NEX REF CONTRACT SERVICES</span></div><img src="${RTBO_LOGO_DATA}" alt="Raising The Bar Officiating"></div><h1>${escapeHtml(normalized.title || 'Agreement')}</h1>${meta ? `<p class="meta">${escapeHtml(meta)}</p>` : ''}${normalized.preamble ? `<p>${safeText(normalized.preamble)}</p>` : ''}${normalized.partyOneName && normalized.partyTwoName ? `<p>This agreement is entered into by and between <strong>${escapeHtml(normalized.partyOneName)}</strong> and <strong>${escapeHtml(normalized.partyTwoName)}</strong>${normalized.effectiveDate ? `, effective ${escapeHtml(formatDate(normalized.effectiveDate))}` : ''}.</p>` : ''}${sections.map(([title, body], index) => `<h2>${index + 1}. ${escapeHtml(title)}</h2><p>${safeText(body)}</p>`).join('')}${normalized.endDate ? `<p><strong>End date:</strong> ${escapeHtml(formatDate(normalized.endDate))}</p>` : ''}<div class="signatures"><div class="signature"><em>${escapeHtml(normalized.partyOneSignature)}</em><strong>${escapeHtml(normalized.partyOneSigner || normalized.partyOneName)}</strong><br>${escapeHtml(normalized.partyOneSignerTitle)}${normalized.partyOneSignedDate ? `<br>${escapeHtml(formatDate(normalized.partyOneSignedDate))}` : ''}</div><div class="signature"><em>${escapeHtml(normalized.partyTwoSignature)}</em><strong>${escapeHtml(normalized.partyTwoSigner || normalized.partyTwoName)}</strong><br>${escapeHtml(normalized.partyTwoSignerTitle)}${normalized.partyTwoSignedDate ? `<br>${escapeHtml(formatDate(normalized.partyTwoSignedDate))}` : ''}</div></div></body></html>`;
  }

  function sendContractToDashboard(contract, options = {}) {
    const normalized = normalizeContract(contract);
    if (window.parent === window || !normalized.id) return;
    const signed = Boolean(normalized.partyOneSignature && normalized.partyTwoSignature);
    const status = signed ? 'Signed' : (normalized.status || 'Draft');
    window.parent.postMessage({ type: 'gunr-document-save', payload: {
      source: 'contract-generator', sourceId: normalized.id, name: contractFilename(normalized, 'html'), type: 'text/html',
      documentCategory: 'contracts', status,
      description: [normalized.partyOneName, normalized.partyTwoName].filter(Boolean).join(' ↔ '),
      tags: [normalized.contractNumber, normalized.governingState, normalized.sourceTemplateFile].filter(Boolean),
      activity: options.activity || (status === 'Draft' ? 'Auto-saved' : 'Generated'), silent: options.silent === true,
      content: documentHtml(normalized)
    } }, '*');
  }

  function syncAllContractsToDashboard() {
    if (window.parent === window) return;
    contracts.filter((contract) => contract?.id).forEach((contract) => sendContractToDashboard(contract, { silent: true, activity: 'Synced' }));
  }

  function downloadHtml(contract) {
    sendContractToDashboard(contract, { activity: 'Generated' });
    downloadFile(contractFilename(contract, 'html'), documentHtml(contract), 'text/html');
  }

  function downloadFile(filename, content, type) {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
})();
